"""Render the API contract (OpenAPI) as YAML.

Used by scripts/export_openapi.py (writes the file) and by
tests/test_openapi_contract.py (checks the committed file is up to date).
The API itself never imports this module.
"""

from pathlib import Path

from fastapi import FastAPI

# backend/src/queryrag/openapi_contract.py -> repo root is 3 folders up
CONTRACT_PATH = Path(__file__).resolve().parents[3] / "docs" / "api" / "openapi.yaml"

HEADER = (
    "# QueryRAG API contract.\n"
    "# GENERATED by scripts/export_openapi.py. Do not edit by hand.\n"
)


def render_openapi_yaml(app: FastAPI) -> str:
    import yaml  # dev dependency: only the export script and tests need it

    body = yaml.safe_dump(
        app.openapi(),
        sort_keys=False,
        allow_unicode=True,
        width=100,
    )

    return HEADER + body